// src/pages/Register.js
import React from 'react';
import { Link } from 'react-router-dom';
import './Auth.css'; // shared CSS file for login/register

function Register() {
  return (
    <div className="auth-container">
      <div className="auth-box">
        <h2 className="auth-title">Register for MediVault Pro</h2>
        <form>
          <input type="text" placeholder="Full Name" className="auth-input" required />
          <input type="email" placeholder="Email" className="auth-input" required />
          <input type="password" placeholder="Password" className="auth-input" required />
          <input type="password" placeholder="Confirm Password" className="auth-input" required />
          <button type="submit" className="auth-button">Register</button>
        </form>
        <p className="auth-link-text">
          Already have an account? <Link to="/lo" className="auth-link">Login</Link>
        </p>
      </div>
    </div>
  );
}

export default Register;
